CREATE TABLE "Opportunity" (
 "id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"missionId" TEXT,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"source" TEXT NOT NULL,"customer" TEXT NOT NULL,"market" TEXT NOT NULL,"problem" TEXT NOT NULL,"proposedSolution" TEXT NOT NULL,"evidence" TEXT[],"scores" JSONB NOT NULL,"totalScore" INTEGER NOT NULL,"confidence" INTEGER NOT NULL,"evidenceQuality" TEXT NOT NULL,"unknowns" TEXT[],"recommendedExperiment" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'CANDIDATE',"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Opportunity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpportunityRedTeam" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"reviewerAgentId" TEXT NOT NULL,"failureModes" TEXT[],"challengedAssumptions" TEXT[],"evidence" TEXT[],"cheapestDisproof" TEXT NOT NULL,"securityRisks" TEXT[],"legalRisks" TEXT[],"economicRisks" TEXT[],"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OpportunityRedTeam_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OpportunityDecision" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"decision" TEXT NOT NULL,"rationale" TEXT NOT NULL,"options" TEXT[],"assumptions" TEXT[],"expectedResult" TEXT,"actualResult" TEXT,"lesson" TEXT,"decidedBy" TEXT NOT NULL,"decidedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OpportunityDecision_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Opportunity_companyId_status_createdAt_idx" ON "Opportunity"("companyId","status","createdAt");CREATE UNIQUE INDEX "OpportunityRedTeam_opportunityId_key" ON "OpportunityRedTeam"("opportunityId");CREATE INDEX "OpportunityDecision_opportunityId_decidedAt_idx" ON "OpportunityDecision"("opportunityId","decidedAt");
ALTER TABLE "Opportunity" ADD CONSTRAINT "Opportunity_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Opportunity" ADD CONSTRAINT "Opportunity_missionId_fkey" FOREIGN KEY("missionId") REFERENCES "Mission"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "OpportunityRedTeam" ADD CONSTRAINT "OpportunityRedTeam_opportunityId_fkey" FOREIGN KEY("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "OpportunityDecision" ADD CONSTRAINT "OpportunityDecision_opportunityId_fkey" FOREIGN KEY("opportunityId") REFERENCES "Opportunity"("id") ON DELETE CASCADE ON UPDATE CASCADE;
